{
  "name": "实验数据分组",
  "name_en": "Data Group",
  "manufacturer": "Nion",
  "description": "这是实验数据分析软件中的数据分组对象，用于在项目内组织显示项和子分组，便于分层管理图像、谱图等实验结果。它不是物理实验仪器。",
  "description_en": "This is a data-group object in scientific data analysis software, used to organize display items and nested groups within a project for hierarchical management of images, spectra, and other experimental results. It is not a physical laboratory device.",
  "tag_hints": [
    "data organization",
    "project hierarchy",
    "display item grouping",
    "scientific image analysis",
    "Nion Swift"
  ],
  "actions": [
    {
      "action_name": "auto-title",
      "description": "获取/设置数据组标题",
      "description_en": "Get/set the data group title"
    },
    {
      "action_name": "auto-display_item_specifiers",
      "description": "获取/设置显示项标识符列表",
      "description_en": "Get/set the list of display item specifiers"
    },
    {
      "action_name": "auto-data_groups",
      "description": "获取子数据组列表",
      "description_en": "Get the list of child data groups"
    },
    {
      "action_name": "auto-project",
      "description": "获取所属项目",
      "description_en": "Get the parent project"
    },
    {
      "action_name": "auto-create_proxy",
      "description": "创建该数据组的代理对象",
      "description_en": "Create a proxy object for this data group"
    },
    {
      "action_name": "auto-item_specifier",
      "description": "获取该数据组的项目标识",
      "description_en": "Get the item specifier for this data group"
    },
    {
      "action_name": "auto-connect_display_items",
      "description": "连接该数据组中的显示项",
      "description_en": "Connect the display items in this data group"
    },
    {
      "action_name": "auto-disconnect_display_items",
      "description": "断开该数据组中的显示项连接",
      "description_en": "Disconnect the display items in this data group"
    },
    {
      "action_name": "auto-append_display_item",
      "description": "向数据组末尾添加显示项",
      "description_en": "Append a display item to the data group"
    },
    {
      "action_name": "auto-insert_display_item",
      "description": "在指定位置插入显示项",
      "description_en": "Insert a display item at a specified position"
    },
    {
      "action_name": "auto-remove_display_item",
      "description": "从数据组中移除显示项",
      "description_en": "Remove a display item from the data group"
    },
    {
      "action_name": "auto-display_items",
      "description": "获取显示项列表",
      "description_en": "Get the list of display items"
    },
    {
      "action_name": "auto-append_data_group",
      "description": "向当前数据组末尾添加子数据组",
      "description_en": "Append a child data group"
    },
    {
      "action_name": "auto-insert_data_group",
      "description": "在指定位置插入子数据组",
      "description_en": "Insert a child data group at a specified position"
    },
    {
      "action_name": "auto-remove_data_group",
      "description": "移除子数据组",
      "description_en": "Remove a child data group"
    },
    {
      "action_name": "auto-counted_display_items",
      "description": "获取已计数的显示项集合",
      "description_en": "Get the counted display item collection"
    },
    {
      "action_name": "auto-update_counted_display_items",
      "description": "更新已计数的显示项集合",
      "description_en": "Update the counted display item collection"
    },
    {
      "action_name": "auto-subtract_counted_display_items",
      "description": "从已计数的显示项集合中扣除指定项",
      "description_en": "Subtract specified items from the counted display item collection"
    }
  ]
}

